function product_upload(array $file): ?string {
  if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;
  if(($file['error']??0)!==UPLOAD_ERR_OK)throw new RuntimeException('No se pudo subir la imagen.');
  if((int)($file['size']??0)>5*1024*1024)throw new RuntimeException('La imagen supera el máximo de 5 MB.');
  $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
  if(!isset($allowed[$mime]))throw new RuntimeException('Formato de imagen no permitido. Usa JPG, PNG o WEBP.');
  $dir=__DIR__.'/../uploads/products';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('No se pudo crear la carpeta de imágenes.');
  $name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$dest=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$dest))throw new RuntimeException('No se pudo guardar la imagen.');
  return '/uploads/products/'.$name;
}
function product_delete_file(?string $path):void{if(!$path)return;$base=realpath(__DIR__.'/../uploads/products');$file=realpath(__DIR__.'/..'.$path);if($base&&$file&&str_starts_with($file,$base.DIRECTORY_SEPARATOR)&&is_file($file))@unlink($file);}
