    $newImage=product_upload($_FILES['image']??[]);
    if($id>0){$old=$pdo->prepare('SELECT * FROM cp_products WHERE id=?');$old->execute([$id]);$found=$old->fetch();if(!$found)throw new RuntimeException('Producto no encontrado.');$s=$pdo->prepare('UPDATE cp_products SET category_id=?,name=?,sku=?,description=?,sale_price=?,purchase_price=?,pricing_type=?,visible_web=?,enabled=?,updated_at=NOW() WHERE id=?');$s->execute([$product['category_id'],$product['name'],$product['sku']?:null,$product['description']?:null,$product['sale_price']!==''?$product['sale_price']:null,$product['purchase_price']!==''?$product['purchase_price']:null,$product['pricing_type'],$product['visible_web'],$product['enabled'],$id]);if($newImage){$oldImg=$pdo->prepare('SELECT path FROM cp_product_images WHERE product_id=? AND enabled=1 ORDER BY sort_order,id LIMIT 1');$oldImg->execute([$id]);product_delete_file($oldImg->fetchColumn()?:null);$pdo->prepare('DELETE FROM cp_product_images WHERE product_id=?')->execute([$id]);$im=$pdo->prepare('INSERT INTO cp_product_images(product_id,path,alt_text,sort_order,enabled,created_at) VALUES(?,?,?,?,1,NOW())');$im->execute([$id,$newImage,$product['name'],0]);}log_activity('update','products','Producto #'.$id.' actualizado');redirect('/admin/productos.php?saved=updated');}
    else{$s=$pdo->prepare('INSERT INTO cp_products(source_type,category_id,name,sku,description,sale_price,purchase_price,pricing_type,visible_web,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute(['local',$product['category_id'],$product['name'],$product['sku']?:null,$product['description']?:null,$product['sale_price']!==''?$product['sale_price']:null,$product['purchase_price']!==''?$product['purchase_price']:null,$product['pricing_type'],$product['visible_web'],$product['enabled']]);$newId=(int)$pdo->lastInsertId();if($newImage){$im=$pdo->prepare('INSERT INTO cp_product_images(product_id,path,alt_text,sort_order,enabled,created_at) VALUES(?,?,?,?,1,NOW())');$im->execute([$newId,$newImage,$product['name'],0]);}log_activity('create','products','Producto #'.$newId.' creado');redirect('/admin/productos.php?saved=created');}
  }catch(Throwable $e){$error='No se pudo guardar el producto: '.$e->getMessage();}
 }
}
