$rows=[];if($action==='list'){if($q!==''){$s=$pdo->prepare("SELECT p.*,c.name category_name,(SELECT path FROM cp_product_images i WHERE i.product_id=p.id AND i.enabled=1 ORDER BY i.sort_order,i.id LIMIT 1) image_path FROM cp_products p LEFT JOIN cp_categories c ON c.id=p.category_id WHERE p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ? ORDER BY p.id DESC LIMIT 100");$like='%'.$q.'%';$s->execute([$like,$like,$like]);$rows=$s->fetchAll();}else{$rows=$pdo->query("SELECT p.*,c.name category_name,(SELECT path FROM cp_product_images i WHERE i.product_id=p.id AND i.enabled=1 ORDER BY i.sort_order,i.id LIMIT 1) image_path FROM cp_products p LEFT JOIN cp_categories c ON c.id=p.category_id ORDER BY p.id DESC LIMIT 100")->fetchAll();}}
